typedef unsigned int size_t;

struct sceCdlFILE
{
  unsigned int lsn;
  unsigned int size;
  char name[16];
  unsigned char date[8];
};

struct nvlMovieSource
{
  int refs;
  char *filename;
  void *buf;
  int bufsize;
};

extern int nvlSystemInitialized;
extern void *(*nvlAllocFunc)(int, int);
extern "C" int toupper(int);
extern "C" int sceOpen(const char *, int);
extern "C" int sceClose(int);
extern "C" int sceCdSearchFile(sceCdlFILE *, const char *);
extern "C" void *malloc(size_t);
extern "C" void *memset(void *, int, size_t);
extern "C" size_t strlen(const char *);
extern "C" char *strcpy(char *, const char *);
extern "C" void __assert(const char *, int, const char *);

#define SCE_RDONLY 1
#define assert(x) ((x) ? (void)0 : __assert("C:/NVL/ps2/nvl_ps2.cpp", __LINE__, #x))

nvlMovieSource *nvlLoadMovieSource( const char* filename, int buffer_size, void* buffer )
{
  nvlMovieSource  *rv = NULL;
  char            hostStr[] = "HOST";
  const char      *sp, *hp;
  int             hostFile = 1, found = 0;
  sceCdlFILE      fp;

  assert( nvlSystemInitialized );
  assert( filename );
  for( sp = filename, hp = hostStr; *sp && *hp; sp++, hp++ )
  {
    if( toupper(*sp) != *hp )
    {
      hostFile = 0;
      break;
    }
  }
  if( hostFile && ((sp[0] == ':') || ((sp[0] == '0' || sp[0] == '1') && sp[1] == ':')) )
  {
    int fh = sceOpen( filename, SCE_RDONLY );

    if( fh >= 0 )
    {
      found = 1;
      sceClose( fh );
    }
  }
  else if( sceCdSearchFile(&fp, filename) )
  {
    found = 1;
  }
  if( found )
  {
    if( nvlAllocFunc )
    {
      rv = (nvlMovieSource*)(*nvlAllocFunc)( 1, sizeof(nvlMovieSource) );
    }
    else
    {
      rv = (nvlMovieSource*)malloc( sizeof(nvlMovieSource) );
    }
    assert( rv );
    memset( rv, 0, sizeof(nvlMovieSource) );
    if( nvlAllocFunc )
    {
      rv->filename = (char*)(*nvlAllocFunc)( 1, strlen(filename) + 1 );
    }
    else
    {
      rv->filename = (char*)malloc( strlen(filename) + 1 );
    }
    assert( rv );
    strcpy( rv->filename, filename );
    rv->buf = buffer;
    rv->bufsize = buffer_size;
  }
  return rv;
}
